@page "/dashboard"
@using sv_bf7b50e55a0744d2b97dfb65b50def20.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text fs-4">
            <strong>@WarehouseState.CurrentWarehouseName</strong>
            <span class="text-muted">(@WarehouseState.CurrentWarehouseId)</span>
        </p>
    </div>
</div>

<div class="row">
    <div class="col-md-4">
        <div class="card @(AlertService.LatestLowStockCount > 10 ? "border-danger" : AlertService.LatestLowStockCount > 5 ? "border-warning" : "border-success")">
            <div class="card-body text-center">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="display-4 @(AlertService.LatestLowStockCount > 10 ? "text-danger" : AlertService.LatestLowStockCount > 5 ? "text-warning" : "text-success")">
                    @AlertService.LatestLowStockCount
                </p>
                <p class="text-muted">items below minimum level</p>
                @if (_isPolling)
                {
                    <span class="badge bg-info">Polling active — every 10s</span>
                }
            </div>
        </div>
    </div>
    <div class="col-md-8">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Activity Log</h5>
                <ul class="list-group list-group-flush" style="max-height: 300px; overflow-y: auto;">
                    @foreach (var entry in _log)
                    {
                        <li class="list-group-item">@entry</li>
                    }
                </ul>
            </div>
        </div>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private bool _isPolling;
    private readonly List<string> _log = [];
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(() =>
        {
            _log.Insert(0, $"[{DateTime.Now:HH:mm:ss}] Switched to {WarehouseState.CurrentWarehouseName}");
            StateHasChanged();
        });
        WarehouseState.OnChange += _warehouseHandler;

        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertDataChanged += _alertHandler;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            StartPolling();
        }
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _isPolling = true;

        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fetch immediately on start
        await FetchAndNotifyAsync();
        await InvokeAsync(StateHasChanged);

        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await FetchAndNotifyAsync();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose
        }
    }

    private async Task FetchAndNotifyAsync()
    {
        var count = await AlertService.GetLowStockCountAsync(WarehouseState.CurrentWarehouseId);
        _log.Insert(0, $"[{DateTime.Now:HH:mm:ss}] Polled {WarehouseState.CurrentWarehouseId}: {count} low-stock items");
        if (_log.Count > 50) _log.RemoveRange(50, _log.Count - 50);

        // Notify ALL subscribers (sidebar badge, this page, any other component)
        AlertService.NotifyAlertDataChanged(count);
    }

    public void Dispose()
    {
        _isPolling = false;
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();

        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;
        if (_alertHandler is not null)
            AlertService.OnAlertDataChanged -= _alertHandler;
    }
}

